#!/usr/bin/env python3
"""Validate Equinet A2 Step 6 model, tool, permission and quota configuration."""
from __future__ import annotations
import hashlib,json
from pathlib import Path
import yaml
ROOT=Path(__file__).resolve().parents[1];CONFIG=ROOT/'config.yaml';POLICY=ROOT/'foundations/contracts/runtime/a2-runtime-policy-0.1.0-draft.1.yaml';DEFAULT=Path('/opt/data/config.yaml');STEP5=ROOT/'evaluations/step5e/acceptance-record.json';E=ROOT/'evaluations/step6';OUT=E/'technical-validation.json';REVIEW=E/'A2-STEP-6-REVIEW.md';MANIFEST=E/'step6-draft-package-manifest.json';PRIMARY_RESULT=E/'gateway-smoke/primary-result.json';PRIMARY_V2=E/'gateway-smoke/primary-result-v2.json';PRIMARY_VALIDATION=E/'gateway-smoke/primary-validation.json';SMOKE_VALIDATOR=ROOT/'scripts/validate_step6_gateway_smoke.py'
def load_yaml(p):return yaml.safe_load(p.read_text(encoding='utf-8'))
def load_json(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 failures=[];checks={};c=load_yaml(CONFIG);p=load_yaml(POLICY);d=load_yaml(DEFAULT);s5=load_json(STEP5)
 checks['step5_approved']=s5.get('decision')=='approved_and_promoted' and s5.get('next_gate')=='Step 6 — Model, Tools, Permissions and Quotas'
 checks['unitalk_gateway_pattern']=c['model'].get('provider')==d['model'].get('provider')=='openai-api' and c['model'].get('provider_name')==d['model'].get('provider_name')=='litellm-unitalk' and 'api_key' not in c['model']
 checks['primary_model']=c['model'].get('default')=='deepseek-v4-flash' and p['model_routing']['primary']['upstream_provider']=='microsoft_azure'
 checks['fallback_model']=c.get('fallback_providers')==[{'provider':'openai-api','model':'Gemini 3.7 Flash'}] and p['model_routing']['fallback']['upstream_provider']=='google'
