 checks['native_controls']=c['model'].get('max_tokens')==4000 and c['agent']=={'max_turns':50,'api_max_retries':1,'reasoning_effort':'medium'}
 expected={'clarify','code_execution','file','skills','terminal','todo'};actual=set(c['platform_toolsets']['cli']);checks['local_tool_allowlist']=actual==expected and not actual.intersection({'web','browser','computer_use','memory','session_search','delegation','cronjob'})
 ip=p['integration_permissions'];checks['integrations_disabled']=all(v is False for v in ip.values())
