 live={'primary_model_call':'functional_smoke_pass_upstream_telemetry_pending' if functional_primary else 'response_observed_gateway_telemetry_pending' if primary_validation and primary_validation.get('session_response_observed') else 'not_executed','primary_functional_smoke_accepted_for_synthetic':functional_primary,'primary_upstream_route_verified':bool(primary_validation and primary_validation.get('gateway_route_verified')),'primary_validation_reference':str(PRIMARY_VALIDATION.relative_to(ROOT)) if primary_validation else None,'fallback_model_call':'configured_not_tested','promotion_blocked_for_synthetic':not functional_primary,'real_data_activation_blocked':True,'fallback_route_test_required_before_real_data':True}
 result={'step':'6','version':'0.1.0-draft.1','status':'ready_for_promotion_synthetic_local_only' if not failures and functional_primary else 'configured_static_validation_pass_live_gateway_smoke_pending' if not failures else 'validation_failed','profile':'equinet-a2-enrichment','checks':checks,'static_checks':{'total':len(checks),'passed':sum(checks.values())},'model_routing':{'primary':'deepseek-v4-flash','primary_upstream':'microsoft_azure','fallback':'Gemini 3.7 Flash','fallback_upstream':'google','gateway':'litellm-unitalk'},'live_route_validation':live,'enabled_toolsets':sorted(actual),'integration_permissions':ip,'quota_state':{'configured_local_limits':True,'cumulative_token_thresholds':'pending_baseline','budget_scope':'unitalk_mustad_global'},'external_calls':0,'external_actions':0,'approval_required':True,'promotion_performed':False,'promotion_scope':'synthetic_local_only','real_data_authorized':False,'profile_status':'FOUNDATION CONFIGURED — NOT PILOT-READY','next_gate':'Step 7 — Synthetic End-to-End Acceptance after Step 6 approval','failures':failures,'pass':not failures};E.mkdir(parents=True,exist_ok=True);OUT.write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n')
 v2=(primary_validation or {}).get('v2_validation',{});primary_note=('A primary session response was observed and the V2.1 contract-bound business task and audit both passed. LiteLLM request telemetry remains unavailable, so the upstream route is configuration-confirmed but not independently verified.' if v2.get('business_contract_pass') and v2.get('audit_pass') else 'A primary session response was observed and the business task passed, but its audit remains incomplete.' if v2.get('business_contract_pass') else 'A primary session response was observed, but the smoke receipt remains incomplete.' if primary_validation else 'No primary session response has been recorded.')
 decisions=[('S6-1','Route A2 through the Unitalk AI Gateway managed by LiteLLM; no customer API key.'),('S6-2','Use deepseek-v4-flash as primary, routed by LiteLLM to Microsoft Azure.'),('S6-3','Use Gemini 3.7 Flash as one-shot technical fallback, routed by LiteLLM to Google.'),('S6-4','Use 4,000 maximum output tokens, 50 model iterations, one retry before fallback and medium reasoning.'),('S6-5','Enable only clarify, code execution, file, skills, terminal and todo in the local baseline.'),('S6-6','Keep Web, providers, Twenty, HubSpot, n8n, outreach and durable handoffs disabled.'),('S6-7','Allow Sales Lead, Sales Operations/CRM and Prospecting roles; keep named reviewers pending.'),('S6-8','Use the global Unitalk–Mustad USD 5,000 budget with 50/80/100 percent thresholds and no A2 allocation yet.'),('S6-9','Use local audit artifacts now; keep retention, admin visibility and external audit sink pending.'),('S6-10','Allow Step 6 promotion for synthetic local testing after a compliant primary response; keep upstream telemetry, fallback verification, provider regions and retention as mandatory gates before any real Mustad/Equinet data.')];rows='\n'.join(f'| {i} | {x} |' for i,x in decisions);REVIEW.write_text(f'''# Decision Review — Step 6 Model, Tools, Permissions and Quotas\n\n**Status:** `CONFIGURED — STATIC VALIDATION PASS — LIVE GATEWAY SMOKE PENDING`  \n**Profile:** `equinet-a2-enrichment`\n\n## Confirmed configuration\n\n- Primary: `deepseek-v4-flash` via Unitalk AI Gateway / LiteLLM / Microsoft Azure.\n- Fallback: `Gemini 3.7 Flash` via Unitalk AI Gateway / LiteLLM / Google.\n- Static checks: **{sum(checks.values())}/{len(checks)} PASS**.\n- External calls/actions during configuration: **0/0**.\n\n## Decisions\n\n| ID | Decision |\n|---|---|\n{rows}\n\n## Remaining gate\n\n{primary_note} A controlled fallback-route test is also required. Provider region, retention and DPA evidence remain pending.\n''')
